    BEFORE UPDATE ON timi_risk_score_for_acute_coronary_syndrome_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE timi_risk_score_for_acute_coronary_syndrome_grade_flag IS
